using Microsoft.Data.Sqlite;
namespace Brs.Local.Accounts;
internal static class ExpeditionSchema
{
 internal static readonly Dictionary<string,string> Tables=new(StringComparer.Ordinal)
 {
  ["expedition_slots"]="CREATE TABLE expedition_slots ( account_id INTEGER NOT NULL REFERENCES accounts(account_id), slot_no INTEGER NOT NULL CHECK(slot_no BETWEEN 1 AND 3), last_expedition_id INTEGER NOT NULL CHECK(last_expedition_id>0), last_card_ids_json TEXT NOT NULL CHECK(json_valid(last_card_ids_json) AND json_type(last_card_ids_json)='array' AND json_array_length(last_card_ids_json)=3), current_run_id INTEGER, PRIMARY KEY(account_id,slot_no), FOREIGN KEY(account_id,slot_no,current_run_id) REFERENCES expedition_runs(account_id,slot_no,id) ) STRICT",
  ["expedition_runs"]="CREATE TABLE expedition_runs ( id INTEGER PRIMARY KEY AUTOINCREMENT CHECK(id BETWEEN 1 AND 2147483647), account_id INTEGER NOT NULL, slot_no INTEGER NOT NULL CHECK(slot_no BETWEEN 1 AND 3), expedition_id INTEGER NOT NULL CHECK(expedition_id>0), config_hash TEXT NOT NULL CHECK(length(config_hash)=64), frozen_json TEXT NOT NULL CHECK(json_valid(frozen_json) AND json_type(frozen_json)='object'), roster_json TEXT NOT NULL CHECK(json_valid(roster_json) AND json_type(roster_json)='array' AND json_array_length(roster_json)=3), started_at INTEGER NOT NULL CHECK(started_at>0), scheduled_end_at INTEGER NOT NULL CHECK(scheduled_end_at>started_at), end_at INTEGER NOT NULL CHECK(end_at>=started_at AND end_at<=scheduled_end_at), state INTEGER NOT NULL CHECK(state IN(0,1,2)), finished_at INTEGER NOT NULL CHECK(finished_at>=0), result_json TEXT NOT NULL CHECK(json_valid(result_json) AND json_type(result_json)='object'), skip_at INTEGER NOT NULL CHECK(skip_at>=0), skip_paid_qty INTEGER NOT NULL CHECK(skip_paid_qty>=0), skip_free_qty INTEGER NOT NULL CHECK(skip_free_qty>=0), dispatch_retry_hash BLOB NOT NULL CHECK(typeof(dispatch_retry_hash)='blob' AND length(dispatch_retry_hash)=32), skip_retry_hash BLOB CHECK(skip_retry_hash IS NULL OR (typeof(skip_retry_hash)='blob' AND length(skip_retry_hash)=32)), finish_retry_hash BLOB CHECK(finish_retry_hash IS NULL OR (typeof(finish_retry_hash)='blob' AND length(finish_retry_hash)=32)), UNIQUE(account_id,slot_no,id), FOREIGN KEY(account_id,slot_no) REFERENCES expedition_slots(account_id,slot_no), FOREIGN KEY(account_id,dispatch_retry_hash) REFERENCES economy_transactions(account_id,retry_hash) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(account_id,skip_retry_hash) REFERENCES economy_transactions(account_id,retry_hash) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(account_id,finish_retry_hash) REFERENCES economy_transactions(account_id,retry_hash) DEFERRABLE INITIALLY DEFERRED, CHECK((state=0 AND finished_at=0 AND finish_retry_hash IS NULL) OR (state IN(1,2) AND finished_at>0 AND finish_retry_hash IS NOT NULL)), CHECK((skip_at=0 AND skip_paid_qty=0 AND skip_free_qty=0 AND skip_retry_hash IS NULL) OR (skip_at>=started_at AND skip_retry_hash IS NOT NULL AND skip_paid_qty+skip_free_qty>0)) ) STRICT",
  ["ix_expedition_pending_slot"]="CREATE UNIQUE INDEX ix_expedition_pending_slot ON expedition_runs(account_id,slot_no) WHERE state=0",
  ["expedition_allocations"]="CREATE TABLE expedition_allocations ( account_id INTEGER NOT NULL, card_id INTEGER NOT NULL CHECK(card_id>0), slot_no INTEGER NOT NULL CHECK(slot_no BETWEEN 1 AND 3), run_id INTEGER NOT NULL, PRIMARY KEY(account_id,card_id), FOREIGN KEY(account_id,card_id) REFERENCES owned_cards(account_id,card_id), FOREIGN KEY(account_id,slot_no,run_id) REFERENCES expedition_runs(account_id,slot_no,id) ) STRICT",
 };
 internal static void Create(SqliteConnection c,SqliteTransaction t)
 {using var q=c.CreateCommand();q.Transaction=t;q.CommandText=string.Join(';',Tables.Values)+";";q.ExecuteNonQuery();}
}
